        :clear-icon="false"
        v-model="warrantyDate"
        placeholder="请选择保修日期"
      />
    </view>

    <!-- 状态选择 -->
    <view class="status-section">
      <text class="status-label">状态</text>
      <view class="status-buttons">
        <view 
          v-for="(item, index) in statusList" 
          :key="index"
          class="status-btn"
          :class="{ 'active': selectedStatus === item }"
          @click="selectedStatus = item"
        >
          {{ item }}
        </view>
      </view>
    </view>

