<script setup>
import { ref, watch, defineProps, defineEmits } from 'vue';
import Dropdown from '@/components/common/Dropdown.vue';
import CameraUpload from '@/components/common/CameraUpload.vue'

// 定义props，接收编辑数据
const props = defineProps({
  assetData: {
    type: Object,
    default: () => ({
      name: '',
      price: '',
      purchaseDate: '',
      warrantyDate: '',
      category: '',
      status: '在用',
      extraFee: '',
      buyReason: ''
    })
  }
});


// 分类列表
const categoryList = ref([
  {
    label: '数码产品',
    value: 1,
    children: [
      { label: '手机', value: 11 },
      { label: '笔记本电脑', value: 12 },
      { label: '平板电脑', value: 13 }
    ]
  },
  {
    label: '家用电器',
    value: 2,
    children: [
      { label: '厨房电器', value: 21 },
      { label: '清洁电器', value: 22 },
      { label: '个人护理', value: 23 }
    ]
  },
  {
    label: '办公设备',
    value: 3,
    children: []  // 空数组，有展开按钮但无内容
  },
  {
    label: '其他',
    value: 4
    // 没有children字段，没有展开按钮
  }
])
// const categoryList = ref(["电子设备", "办公家具", "数码产品", "其他"]);
const selectedCategory = ref(props.assetData.category);

// 资产基础信息
const assetName = ref(props.assetData.name);
const price = ref(props.assetData.price);
const purchaseDate = ref(props.assetData.purchaseDate);
const warrantyDate = ref(props.assetData.warrantyDate);

// 状态列表
const statusList = ref(["在用", "退役", "预购入", "闲置"]);
const selectedStatus = ref(props.assetData.status);

// 附加费用
const extraFee = ref(props.assetData.extraFee);
const addExtraFee = () => {
  console.log("点击添加附加费用");
};

// 购买原因
const buyReason = ref(props.assetData.buyReason || '');

// 监听assetData变化，更新表单
watch(() => props.assetData, (newVal) => {
  selectedCategory.value = newVal.category;
  assetName.value = newVal.name;
  price.value = newVal.price;
  purchaseDate.value = newVal.purchaseDate;
  warrantyDate.value = newVal.warrantyDate;
  selectedStatus.value = newVal.status;
  extraFee.value = newVal.extraFee;
  buyReason.value = newVal.buyReason;
}, { deep: true });

// 暴露表单数据
const emit = defineEmits(['submit']);
const submitForm = () => {
  const formData = {
    name: assetName.value,
    price: price.value,
    buyDate: purchaseDate.value,
    warrantyDate: warrantyDate.value,
    category: selectedCategory.value,
    status: selectedStatus.value,
    extraFee: extraFee.value,
    buyReason: buyReason.value
  };
  emit('submit', formData);
};

/// 事件处理
const handleBuyDateChange = (e) => {
  buyDate.value = e.value;
};

// 处理相机点击事件
const handleCameraClick = () => {
  console.log('Camera clicked');
};

// 暴露表单数据
defineExpose({
  submitForm
});
</script>

